var rm = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var q = function(s){ return root.querySelector(s); };
var clock = q('.trm2-window-clock'), upEl = q('.trm2-window-uptime');
var load = q('.trm2-window-load'), gOn = q('.trm2-window-gauge'), gOff = q('.trm2-window-gauge-off');
var pct = q('.trm2-window-pct'), net = q('.trm2-window-net'), typ = q('.trm2-window-type');
var p2 = function(n){ return (n < 10 ? '0' : '') + n; };
var up = 14 * 86400 + 6 * 3600 + 22 * 60 + 41;
function paintClock(){
  var d = new Date();
  clock.textContent = p2(d.getHours()) + ':' + p2(d.getMinutes()) + ':' + p2(d.getSeconds());
  up += 1;
  upEl.textContent = Math.floor(up / 86400) + 'd ' + p2(Math.floor(up % 86400 / 3600)) + ':' + p2(Math.floor(up % 3600 / 60)) + ':' + p2(up % 60);
}
function rep(ch, n){ var s = ''; for (var i = 0; i < n; i++) s += ch; return s; }
function paintStats(){
  load.textContent = (0.28 + Math.random() * 0.9).toFixed(2) + '  ' + (0.30 + Math.random() * 0.35).toFixed(2) + '  0.31';
  var m = 0.52 + Math.random() * 0.16, cells = 10, on = Math.round(m * cells);
  gOn.textContent = rep('█', on);
  gOff.textContent = rep('░', cells - on);
  pct.textContent = (m * 8).toFixed(1) + 'G/8.0G';
  net.textContent = '▲ ' + (90 + Math.floor(Math.random() * 120)) + 'k/s  ▼ ' + (0.9 + Math.random() * 1.4).toFixed(1) + 'M/s';
}
paintClock(); paintStats();
var cmds = ['tail -f /var/log/sys', 'ps aux | grep mother', 'df -h /dev/sda1', 'uptime --pretty'];
var ci = 0, cp = 0, dir = 1, hold = 0;
function typeStep(){
  if (hold > 0){ hold--; return; }
  var t = cmds[ci];
  if (dir > 0){ cp++; if (cp >= t.length){ cp = t.length; dir = -1; hold = 24; } }
  else { cp -= 2; if (cp <= 0){ cp = 0; dir = 1; ci = (ci + 1) % cmds.length; hold = 4; } }
  typ.textContent = cmds[ci].slice(0, cp);
}
if (rm){ typ.textContent = cmds[0]; }
else {
  setInterval(paintClock, 1000);
  setInterval(paintStats, 2400);
  setInterval(typeStep, 72);
}

