var rm = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var items = root.querySelectorAll('.trm2-menubar-item');
var drop = root.querySelector('.trm2-menubar-drop');
var slot = root.querySelector('.trm2-menubar-rows');
var DASH = '──────────────────────────────';
var MENUS = {
  file: [['','New','Ctrl-N',0],['','Open…','Ctrl-O',0],['','Save','Ctrl-S',0],['sep'],['','Print','Ctrl-P',0],['','Exit','Alt-X',1]],
  edit: [['','Undo','Ctrl-Z',0],['','Cut','Ctrl-X',0],['','Copy','Ctrl-C',0],['','Paste','Ctrl-V',0],['sep'],['','Find…','Ctrl-F',0]],
  run:  [['','Compile','Alt-F9',0],['','Make','F9',0],['sep'],['','Debug','F7',0],['','Trace','F8',0]],
  help: [['','Contents','F1',0],['','Index','Sh-F1',0],['sep'],['','About…','',0]]
};
function render(name){
  var rows = MENUS[name] || MENUS.file, out = '';
  for (var i = 0; i < rows.length; i++){
    var r = rows[i];
    if (r[0] === 'sep'){
      out += '<div class="trm2-menubar-row trm2-menubar-sep"><span class="trm2-menubar-c">├</span><span class="trm2-menubar-fill">' + DASH + '</span><span class="trm2-menubar-c">┤</span></div>';
    } else {
      var t = r[1], h = r[3] || 0;
      var lbl = t.slice(0, h) + '<span class="trm2-menubar-hot">' + t.charAt(h) + '</span>' + t.slice(h + 1);
      out += '<div class="trm2-menubar-row"><span class="trm2-menubar-c">│</span><span class="trm2-menubar-lbl">' + lbl + '</span><span class="trm2-menubar-key">' + r[2] + '</span><span class="trm2-menubar-c">│</span></div>';
    }
  }
  slot.innerHTML = out;
  sel = 0; paint();
}
var sel = 0, auto = true;
function rows(){ return slot.querySelectorAll('.trm2-menubar-row'); }
function paint(){
  var rs = rows();
  for (var i = 0; i < rs.length; i++){
    if (i === sel) rs[i].className = 'trm2-menubar-row trm2-menubar-hl';
    else if (rs[i].className.indexOf('sep') > -1) continue;
    else rs[i].className = 'trm2-menubar-row';
  }
}
function step(d){
  var rs = rows(), n = rs.length, guard = 0;
  do { sel = (sel + d + n) % n; guard++; }
  while (rs[sel] && rs[sel].className.indexOf('sep') > -1 && guard < n + 2);
  paint();
}
function place(el){
  var left = el.offsetLeft;
  var max = root.clientWidth - drop.offsetWidth - 6;
  drop.style.left = Math.max(2, Math.min(left, max)) + 'px';
}
for (var i = 0; i < items.length; i++){
  (function(el){
    el.addEventListener('click', function(){
      auto = false;
      for (var j = 0; j < items.length; j++) items[j].className = 'trm2-menubar-item';
      el.className = 'trm2-menubar-item trm2-menubar-open';
      render(el.getAttribute('data-m'));
      place(el);
    });
  })(items[i]);
}
slot.addEventListener('mouseover', function(e){
  var t = e.target;
  while (t && t !== slot && t.className.indexOf('trm2-menubar-row') < 0) t = t.parentNode;
  if (!t || t === slot || t.className.indexOf('sep') > -1) return;
  auto = false;
  var rs = rows();
  for (var k = 0; k < rs.length; k++) if (rs[k] === t) sel = k;
  paint();
});
place(items[0]);
if (!rm) setInterval(function(){ if (auto) step(1); }, 1250);

var rm = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var rows = root.querySelectorAll('.trm2-listbox-row');
var count = root.querySelector('.trm2-listbox-count');
var n = rows.length, sel = 3, top = 3, TOTAL = 24, auto = true;
function paint(){
  for (var i = 0; i < n; i++){
    rows[i].className = i === sel ? 'trm2-listbox-row trm2-listbox-on' : 'trm2-listbox-row';
    var sb = rows[i].querySelector('.trm2-listbox-sb');
    if (i === 0) sb.textContent = '▲';
    else if (i === n - 1) sb.textContent = '▼';
    else {
      var thumb = 1 + Math.round((top / (TOTAL - 1)) * (n - 3));
      sb.textContent = (i === thumb || i === thumb + 1) ? '█' : '░';
    }
  }
  count.textContent = (top + 1 < 10 ? '0' : '') + (top + 1) + '/' + TOTAL;
}
for (var i = 0; i < n; i++){
  (function(el, idx){
    el.addEventListener('mouseenter', function(){ auto = false; sel = idx; paint(); });
  })(rows[i], i);
}
root.addEventListener('keydown', function(e){
  if (e.key === 'ArrowDown'){ e.preventDefault(); auto = false; if (sel < n - 1){ sel++; } top = (top + 1) % TOTAL; paint(); }
  else if (e.key === 'ArrowUp'){ e.preventDefault(); auto = false; if (sel > 0){ sel--; } top = (top - 1 + TOTAL) % TOTAL; paint(); }
});
paint();
if (!rm) setInterval(function(){
  if (!auto) return;
  sel = (sel + 1) % n;
  top = (top + 1) % TOTAL;
  paint();
}, 1900);

