var btns = root.querySelectorAll('.trm2-dialog-btn');
var res = root.querySelector('.trm2-dialog-res');
var box = root.querySelector('.trm2-dialog-box');
var sel = 0, timer = null;
function paint(){
  for (var i = 0; i < btns.length; i++)
    btns[i].className = i === sel ? 'trm2-dialog-btn trm2-dialog-on' : 'trm2-dialog-btn';
}
function fire(){
  var ok = sel === 0;
  res.textContent = ok ? '▶ deleting 3 objects …' : '▶ cancelled — nothing removed';
  res.className = ok ? 'trm2-dialog-res trm2-dialog-fire' : 'trm2-dialog-res';
  box.style.transform = 'translate(1px,1px)';
  if (timer) clearTimeout(timer);
  timer = setTimeout(function(){
    res.textContent = 'Tab ⇄ switch   ⏎ activate   Esc cancel';
    res.className = 'trm2-dialog-res';
    box.style.transform = '';
  }, 1800);
}
for (var i = 0; i < btns.length; i++){
  (function(el, idx){
    el.addEventListener('mouseenter', function(){ sel = idx; paint(); });
    el.addEventListener('click', function(){ sel = idx; paint(); fire(); });
  })(btns[i], i);
}
root.addEventListener('keydown', function(e){
  var k = e.key;
  if (k === 'ArrowRight' || k === 'ArrowLeft' || k === 'Tab'){
    e.preventDefault(); sel = (sel + 1) % btns.length; paint();
  } else if (k === 'Enter' || k === ' '){
    e.preventDefault(); fire();
  } else if (k === 'Escape'){
    e.preventDefault(); sel = 1; paint(); fire();
  }
});
paint();

var rm = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var q = function(s){ return root.querySelector(s); };
var on = q('.trm2-progress-on'), off = q('.trm2-progress-off'), pct = q('.trm2-progress-pct');
var got = q('.trm2-progress-got'), rate = q('.trm2-progress-rate'), eta = q('.trm2-progress-eta');
var spin = q('.trm2-progress-spin');
var minis = root.querySelectorAll('.trm2-progress-mini');
var CELLS = 24, MCELLS = 12, SIZE = 4.6;
var PART = ' ▏▎▍▌▋▊▉';
var SPIN = ['◐','◓','◑','◒'];
function rep(ch, n){ var s = ''; for (var i = 0; i < n; i++) s += ch; return s; }
function p2(n){ return (n < 10 ? '0' : '') + n; }
function bar(onEl, offEl, cells, p){
  var total = p * cells, full = Math.floor(total);
  if (full >= cells){ onEl.textContent = rep('█', cells); offEl.textContent = ''; return; }
  var frac = Math.floor((total - full) * 8);
  onEl.textContent = rep('█', full) + (frac > 0 ? PART.charAt(frac) : '');
  offEl.textContent = rep('░', cells - full - (frac > 0 ? 1 : 0));
}
var p = 0.14, mp = [0.5, 0.25, 1], si = 0, mbs = 1.8;
function paint(){
  bar(on, off, CELLS, p);
  pct.textContent = (p * 100).toFixed(1) + '%';
  got.textContent = (p * SIZE).toFixed(1) + 'G/' + SIZE.toFixed(1) + 'G';
  rate.textContent = mbs.toFixed(1) + ' MB/s';
  var left = Math.max(0, Math.round((1 - p) * SIZE * 1024 / mbs));
  eta.textContent = 'eta ' + p2(Math.floor(left / 3600)) + ':' + p2(Math.floor(left % 3600 / 60)) + ':' + p2(left % 60);
  for (var i = 0; i < minis.length; i++){
    bar(minis[i].querySelector('.trm2-progress-on'), minis[i].querySelector('.trm2-progress-off'), MCELLS, mp[i]);
    var el = minis[i].querySelector('.trm2-progress-mp');
    el.textContent = Math.round(mp[i] * 100) + '%';
    el.style.color = mp[i] >= 1 ? '#6dff9d' : '';
  }
}
function step(){
  p += 0.004 + Math.random() * 0.012;
  if (p >= 1){ p = 0; }
  mbs = 1.2 + Math.random() * 1.4;
  mp[0] = Math.min(1, mp[0] + 0.01);
  mp[1] = Math.min(1, mp[1] + 0.006);
  if (mp[0] >= 1 && mp[1] >= 1){ mp[0] = 0; mp[1] = 0; }
  si = (si + 1) % SPIN.length;
  spin.textContent = SPIN[si];
  paint();
}
paint();
if (!rm) setInterval(step, 140);

