var rm = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var panes = root.querySelectorAll('.trm2-filepanes-pane');
var path = root.querySelector('.trm2-filepanes-path');
var PATHS = ['/usr/src', '/var/log'];
var act = 0, cur = [2, 3], auto = true;
function paint(){
  for (var p = 0; p < panes.length; p++){
    panes[p].className = p === act ? 'trm2-filepanes-pane trm2-filepanes-act' : 'trm2-filepanes-pane';
    var rows = panes[p].querySelectorAll('.trm2-filepanes-row');
    for (var i = 0; i < rows.length; i++){
      var sel = (i === cur[p]) && (p === act);
      rows[i].className = sel ? 'trm2-filepanes-row trm2-filepanes-on' : 'trm2-filepanes-row';
    }
  }
  var rows2 = panes[act].querySelectorAll('.trm2-filepanes-row');
  var nm = rows2[cur[act]].querySelector('.trm2-filepanes-nm').textContent;
  path.textContent = ':' + PATHS[act] + (nm === '..' ? '' : '/' + nm);
}
for (var p = 0; p < panes.length; p++){
  (function(el, idx){
    el.addEventListener('click', function(e){
      auto = false; act = idx;
      var t = e.target;
      while (t && t !== el && t.className.indexOf('trm2-filepanes-row') < 0) t = t.parentNode;
      if (t && t !== el){
        var rows = el.querySelectorAll('.trm2-filepanes-row');
        for (var i = 0; i < rows.length; i++) if (rows[i] === t) cur[idx] = i;
      }
      paint();
    });
  })(panes[p], p);
}
paint();
if (!rm) setInterval(function(){
  if (!auto) return;
  var nrows = panes[act].querySelectorAll('.trm2-filepanes-row').length;
  cur[act] = (cur[act] + 1) % nrows;
  if (cur[act] === 0) act = (act + 1) % 2;
  paint();
}, 1500);

