var rm = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var tabs = root.querySelectorAll('.trm2-tabpanel-tab');
var panes = root.querySelectorAll('.trm2-tabpanel-pane');
var idx = root.querySelector('.trm2-tabpanel-idx');
var spark = root.querySelector('.trm2-tabpanel-sparkline');
var rx = root.querySelector('.trm2-tabpanel-rx'), tx = root.querySelector('.trm2-tabpanel-tx');
var logPane = root.querySelector('.trm2-tabpanel-log');
var cur = 0, auto = true;
function show(i){
  cur = i;
  for (var k = 0; k < tabs.length; k++){
    tabs[k].className = k === i ? 'trm2-tabpanel-tab trm2-tabpanel-on' : 'trm2-tabpanel-tab';
    panes[k].className = k === i ? 'trm2-tabpanel-pane trm2-tabpanel-vis' : 'trm2-tabpanel-pane';
  }
  if (i === 3) panes[3].className = 'trm2-tabpanel-pane trm2-tabpanel-log trm2-tabpanel-vis';
  idx.textContent = (i + 1);
}
for (var k = 0; k < tabs.length; k++){
  (function(el, i){
    el.addEventListener('click', function(){ auto = false; show(i); });
  })(tabs[k], k);
}
var LV = '▁▂▃▄▅▆▇█';
var data = [];
for (var s = 0; s < 28; s++) data.push(Math.floor(Math.random() * 8));
function drawSpark(){
  data.shift();
  var last = data[data.length - 1];
  var nx = last + (Math.random() < 0.5 ? -1 : 1) * (1 + Math.floor(Math.random() * 3));
  if (nx < 0) nx = 0; if (nx > 7) nx = 7;
  data.push(nx);
  var s = '';
  for (var i = 0; i < data.length; i++) s += LV.charAt(data[i]);
  spark.textContent = s;
  rx.textContent = (0.4 + nx * 0.28).toFixed(2);
  tx.textContent = (0.05 + Math.random() * 0.4).toFixed(2);
}
var MSGS = [['ok','sshd: accepted publickey'],['ok','cron: job 44 finished'],['wr','disk 71% used'],['ok','mother: heartbeat'],['wr','retry socket 8080'],['ok','backup: 214 files']];
var lt = 8 * 3600 + 14 * 60 + 52;
function p2(n){ return (n < 10 ? '0' : '') + n; }
function pushLog(){
  var m = MSGS[Math.floor(Math.random() * MSGS.length)];
  lt += 3 + Math.floor(Math.random() * 12);
  var d = document.createElement('div');
  d.className = 'trm2-tabpanel-ll trm2-tabpanel-new';
  d.innerHTML = '<span class="trm2-tabpanel-ts">' + p2(Math.floor(lt / 3600)) + ':' + p2(Math.floor(lt % 3600 / 60)) + ':' + p2(lt % 60) +
    '</span><span class="trm2-tabpanel-' + m[0] + '">' + m[0] + '</span> ' + m[1];
  logPane.appendChild(d);
  while (logPane.children.length > 7) logPane.removeChild(logPane.firstChild);
}
show(0);
if (!rm){
  setInterval(drawSpark, 340);
  setInterval(pushLog, 1600);
  setInterval(function(){ if (auto) show((cur + 1) % 4); }, 4200);
}

