var rm = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var rows = root.querySelectorAll('.trm2-formfields-row');
var hint = root.querySelector('.trm2-formfields-hint');
var uid = root.querySelector('.trm2-formfields-uid');
var GROUPS = ['crew    ', 'science ', 'medical ', 'command '];
var SHELLS = ['zsh', 'bash'];
var f = [
  { type: 'text', v: '', max: 14 },
  { type: 'text', v: '', max: 14 },
  { type: 'pick', i: 0 },
  { type: 'radio', i: 0 },
  { type: 'check', i: 0 }
];
var cur = 0, live = true;
function pad(n){ var s = ''; for (var i = 0; i < n; i++) s += '_'; return s; }
function syncUid(){ uid.textContent = f[0].v ? f[0].v : '_'; }
function paint(){
  for (var i = 0; i < rows.length; i++){
    var on = i === cur;
    rows[i].className = on ? 'trm2-formfields-row trm2-formfields-act' : 'trm2-formfields-row';
    rows[i].querySelector('.trm2-formfields-mark').textContent = on ? '▸' : ' ';
    var d = f[i];
    if (d.type === 'text'){
      rows[i].querySelector('.trm2-formfields-val').textContent = d.v;
      rows[i].querySelector('.trm2-formfields-pad').textContent = pad(Math.max(0, d.max - d.v.length - (on ? 1 : 0)));
      if (i === 0) syncUid();
    } else if (d.type === 'pick'){
      rows[i].querySelector('.trm2-formfields-pick').textContent = '[ ' + GROUPS[d.i] + '▾]';
    } else {
      var opts = rows[i].querySelectorAll('.trm2-formfields-opt');
      if (d.type === 'radio'){
        opts[0].textContent = (d.i === 0 ? '(•) ' : '( ) ') + SHELLS[0];
        opts[1].textContent = (d.i === 1 ? '(•) ' : '( ) ') + SHELLS[1];
      } else {
        opts[0].textContent = (d.i % 2 === 0 ? '[X] ' : '[ ] ') + 'mail';
        opts[1].textContent = (d.i > 0 ? '[X] ' : '[ ] ') + 'pager';
      }
    }
  }
}
function cycle(){
  var d = f[cur];
  if (d.type === 'pick') d.i = (d.i + 1) % GROUPS.length;
  else if (d.type === 'radio') d.i = (d.i + 1) % 2;
  else if (d.type === 'check') d.i = (d.i + 1) % 3;
  paint();
}
function stop(){ live = false; }
for (var i = 0; i < rows.length; i++){
  (function(el, idx){
    el.addEventListener('click', function(){ stop(); if (cur === idx) cycle(); else { cur = idx; paint(); } root.focus(); });
  })(rows[i], i);
}
root.addEventListener('keydown', function(e){
  var k = e.key;
  stop();
  if (k === 'Tab'){ if (cur < rows.length - 1){ e.preventDefault(); cur++; paint(); } return; }
  if (k === 'ArrowDown'){ e.preventDefault(); cur = (cur + 1) % rows.length; paint(); return; }
  if (k === 'ArrowUp'){ e.preventDefault(); cur = (cur - 1 + rows.length) % rows.length; paint(); return; }
  var d = f[cur];
  if (d.type === 'text'){
    if (k === 'Backspace'){ e.preventDefault(); d.v = d.v.slice(0, -1); paint(); }
    else if (k.length === 1 && !e.metaKey && !e.ctrlKey){ e.preventDefault(); if (d.v.length < d.max) d.v += k; paint(); }
  } else if (k === ' ' || k === 'Enter' || k === 'ArrowRight'){ e.preventDefault(); cycle(); }
});
var btns = root.querySelectorAll('.trm2-formfields-btn');
for (var b = 0; b < btns.length; b++){
  (function(el, idx){
    el.addEventListener('click', function(){
      stop();
      hint.textContent = idx === 0 ? '▸ account created — uid 1043' : '▸ cancelled';
      hint.className = idx === 0 ? 'trm2-formfields-hint trm2-formfields-ok' : 'trm2-formfields-hint';
    });
  })(btns[b], b);
}
paint();
var script = [[0, 'ripley'], [1, 'E. Ripley'], [2, 0], [4, 0], [3, 0], [-1, 0]];
var sp = 0, hold = 0;
function demo(){
  if (!live) return;
  if (hold > 0){ hold--; return; }
  var s = script[sp];
  if (s[0] === -1){ f[0].v = ''; f[1].v = ''; f[2].i = 0; f[3].i = 0; f[4].i = 0; cur = 0; sp = 0; paint(); hold = 6; return; }
  cur = s[0];
  var d = f[cur];
  if (d.type === 'text'){
    if (d.v.length < String(s[1]).length){ d.v = String(s[1]).slice(0, d.v.length + 1); paint(); }
    else { sp++; hold = 4; }
  } else { cycle(); sp++; hold = 8; }
}
if (!rm) setInterval(demo, 130); else { f[0].v = 'ripley'; f[1].v = 'E. Ripley'; paint(); }
